<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Customer; use App\Services\AuditService; use Illuminate\Http\Request;
class CustomerController extends Controller { public function index(){return view('admin.resource',['title'=>__('ui.customers'),'columns'=>['name','company_name','email','status'],'rows'=>Customer::latest()->paginate(20),'createRoute'=>route('customers.create')]);} public function create(){return view('admin.form',['title'=>__('ui.new_customer'),'action'=>route('customers.store'),'fields'=>['name'=>'text','company_name'=>'text','email'=>'email','phone'=>'text','notes'=>'textarea','status'=>'select:active,inactive']]);} public function store(Request $r,AuditService $audit){$data=$r->validate(['name'=>'required|max:255','company_name'=>'nullable|max:255','email'=>'nullable|email','phone'=>'nullable|max:50','notes'=>'nullable','status'=>'required|in:active,inactive']);$model=Customer::create($data);$audit->record('customer.created',$model,null,$model->toArray());return redirect()->route('customers.index')->with('success',__('ui.saved'));} }
